"""Offline user journeys and retired-feature migration, using the built HTML."""
from pathlib import Path
from playwright.sync_api import sync_playwright
import hashlib,json
R=Path(__file__).resolve().parents[1];out=R/'data';checks=[]
def check(name,result):
 assert result,name
 checks.append(name)
with sync_playwright() as p:
 browser=p.chromium.launch(executable_path='/usr/bin/chromium',headless=True,args=['--no-sandbox'])
 context=browser.new_context(viewport={'width':1440,'height':1100},accept_downloads=True)
 page=context.new_page();errors=[];page.on('pageerror',lambda e:errors.append(str(e)))
 context.route('**/*',lambda r:r.continue_() if r.request.url.startswith('http://127.0.0.1:8787/') else r.abort())
 # Migrate only planning fields, even if a previous version stored notes/bookmarks/hours.
 context.add_init_script('''if(!localStorage.getItem('canarias360-roadbook-v2'))localStorage.setItem('canarias360-roadbook-v1',JSON.stringify({quotas:[85,70,60,50],progressKm:0,notes:{x:'old private note'},saved:['x'],hoursOverrides:{x:'24/7'}}));''')
 page.goto('http://127.0.0.1:8787/index.html');page.wait_for_function('window.RACER_APP')
 check('app loads without external dependencies or script errors',not errors)
 check('default finish is Sunday morning','Sun 03:45' in page.locator('#finishClock').inner_text())
 check('daily progress is collapsed by default',not page.locator('#pacePanel').evaluate('e=>e.open'))
 check('notes, bookmarks and import/export plan are removed',page.locator('#placeDialog,#importPlan,#planFile,#exportPlan,[data-action=note],[data-action=save]').count()==0)
 check('old notes and hours do not migrate into planning state',set(page.evaluate('Object.keys(RACER_APP.getState())'))=={'quotas','progressKm','elapsedHours','anchorLive','extraHours','terrainWeight','streetMap','vision'})
 check('all 29 legs use readable cards',page.locator('#sectionRows .leg-card').count()==29 and page.locator('#sectionRows table').count()==0)
 check('real source data and route remain loaded',page.evaluate('RACER_APP.DATA.pois.length')==353)
 page.screenshot(path=str(out/'roadbook_desktop.png'),full_page=True)
 page.locator('#pacePanel>summary').click();page.get_by_role('button',name='80 km start',exact=True).click()
 check('slower preset updates cutoff margin','0h 10m' in page.locator('#finishMargin').inner_text())
 page.get_by_role('button',name='85 km start',exact=True).click();page.locator('#pacePanel>summary').click()
 page.get_by_role('tab',name='Resupply',exact=True).click()
 check('resupply shows six stops initially',page.locator('#poiCards article').count()==6)
 check('filters start collapsed',not page.locator('#filtersPanel').evaluate('e=>e.open'))
 page.locator('#showMore').click();check('more adds six stops',page.locator('#poiCards article').count()==12)
 page.locator('#searchPoi').fill('tenteniguada')
 check('search resets pagination and finds supermarket','SPAR Tenteniguada' in page.locator('#poiCards').inner_text())
 stop=page.locator('#poiCards [data-place="owner/spar-tenteniguada"]')
 check('overnight stop shows closed at arrival','Closed at arrival' in stop.inner_text())
 check('hours and sources start folded',not stop.locator('details').evaluate('e=>e.open') and not stop.locator('.hours').is_visible())
 stop.locator('summary').click();check('published schedule and evidence remain available',stop.locator('.hours').is_visible() and stop.get_by_role('link',name='Hours source').is_visible())
 check('front of stop has at most map and call actions',stop.locator(':scope > .actions > *').count()<=2)
 page.locator('#progressKm').fill('100.5');page.locator('#progressKm').blur()
 check('GPS-independent progress updates checkpoint and stop distances','21.1 km' in page.locator('#nextCheckpoint').inner_text())
 check('details stay open after planner refresh',page.locator('#poiCards [data-place="owner/spar-tenteniguada"] details').evaluate('e=>e.open'))
 page.locator('#toolsPanel>summary').click()
 with page.expect_download() as info:page.locator('#downloadHtml').click()
 saved=out/'test_saved_roadbook.html';info.value.save_as(str(saved))
 new=context.new_page();new.on('pageerror',lambda e:errors.append(str(e)));new.goto('http://127.0.0.1:8787/data/test_saved_roadbook.html');new.wait_for_function('window.RACER_APP')
 check('portable HTML retains planning values',new.evaluate('RACER_APP.getState().progressKm')==100.5)
 check('portable HTML opens with settings collapsed and GPS off',not new.locator('#pacePanel').evaluate('e=>e.open') and not new.locator('#location-main').is_checked())
 with page.expect_download() as info:page.locator('#downloadGpx').click()
 gp=out/'test_download.gpx';info.value.save_as(str(gp))
 check('GPX download is byte-identical to original candidate',hashlib.sha256(gp.read_bytes()).hexdigest()==page.evaluate('RACER_APP.DATA.gpx_sha256'))
 page.get_by_role('tab',name='Legs',exact=True).click();page.locator('#sectionRows [data-section="10"]').click();page.wait_for_timeout(120)
 check('leg map works offline',page.locator('#map .leaflet-map-pane').count()==1 and '→' in page.locator('#mapCaption').inner_text())
 check('switching views brings selected content into view',0<=page.locator('.tabs').bounding_box()['y']<100)
 page.screenshot(path=str(out/'roadbook_map.png'),full_page=True)
 before=page.locator('#mapSelection .callout').inner_text()
 page.locator('#pacePanel>summary').click();page.locator('#timingPanel>summary').click();page.locator('#elapsedHours').fill('40');page.locator('#elapsedHours').blur();page.locator('#anchorLive').check()
 check('selected leg arrival refreshes after timing changes',page.locator('#mapSelection .callout').inner_text()!=before)
 page.evaluate("selectPlace(RACER_APP.DATA.pois.find(p=>p.id==='owner/spar-tenteniguada'))")
 check('selecting a shop clears the previous leg highlight',page.evaluate('selectedLine===null&&selectedSectionId===null') and page.locator('#mapSelection .poi-card').count()==1)
 page.evaluate('selectSection(10)')
 check('selecting a leg clears the previous shop approach',page.evaluate('approachLine===null&&selectedPlaceId===null'))
 page.get_by_role('tab',name='Race',exact=True).focus();page.keyboard.press('ArrowRight')
 check('tabs support arrow keyboard navigation',page.locator('#nav-sections').get_attribute('aria-selected')=='true')
 check('no runtime errors throughout journeys',not errors)
 phone=browser.new_context(viewport={'width':390,'height':844},is_mobile=True,has_touch=True);m=phone.new_page();m.goto('http://127.0.0.1:8787');m.wait_for_function('window.RACER_APP');m.screenshot(path=str(out/'roadbook_mobile.png'),full_page=True)
 check('phone overview fits screen',m.evaluate('document.documentElement.scrollWidth<=innerWidth+1'))
 m.get_by_role('tab',name='Resupply',exact=True).click();m.evaluate('window.scrollTo(0,0)');m.screenshot(path=str(out/'roadbook_resupply_mobile.png'),full_page=True)
 check('phone resupply fits screen',m.evaluate('document.documentElement.scrollWidth<=innerWidth+1'))
 browser.close()
result={'passed':len(checks),'checks':checks,'script_errors':errors};(R/'docs/browser_tests.json').write_text(json.dumps(result,indent=2));print(json.dumps(result,indent=2))
